const E=FortuneEngine,$=id=>document.getElementById(id),config=window.AppConfig||{};
let active='',current=null,generation=0,shareReady=false;
const modes={saju:{title:'우리 아이의 사주',intro:'생일에 담긴 기질과 마음을 읽어보세요.',button:'사주 풀이 보기',kind:'saju'},guardian:{title:'보호자와 궁합',intro:'서로 어떤 온기를 나누는 인연일까요?',button:'우리 궁합 보기',kind:'pair'},friends:{title:'강아지 친구와 궁합',intro:'두 아이가 함께 만드는 인연을 읽어보세요.',button:'친구 궁합 보기',kind:'saju'}};
function clearResult(){generation++;if(current)URL.revokeObjectURL(current.url);current=null;$('resultStage').hidden=true;$('status').textContent='';$('manualCopy').hidden=true;}
function syncModeLabels(){for(const prefix of ['pet','friend']){$(prefix+'DateLabel').textContent=$(prefix+'Mode').value==='adoption'?'함께 살기 시작한 날':'생년월일';}}
function choose(tab,updateHistory=true){if(!modes[tab])return;clearResult();active=tab;const m=modes[tab];$('welcome').hidden=true;$('inputStage').hidden=false;$('formTitle').textContent=m.title;$('formIntro').textContent=m.intro;$('submit').textContent=m.button;$('ownerFields').hidden=tab!=='guardian';$('ownerFields').disabled=tab!=='guardian';$('ownerDate').required=tab==='guardian';$('friendFields').hidden=tab!=='friends';$('friendFields').disabled=tab!=='friends';$('friendDate').required=tab==='friends';$('error').textContent='';$('form').removeAttribute('aria-busy');$('submit').disabled=false;document.querySelectorAll('[data-tab]').forEach(b=>{const selected=b.dataset.tab===tab;b.setAttribute('aria-selected',selected);b.tabIndex=selected?0:-1;});$('flow').setAttribute('aria-labelledby','tab-'+tab);$('previewTitle').textContent=m.title;$('previewImg').src=`assets/${m.kind}.png`;$('previewCaption').textContent=tab==='friends'?'나란히 걷는 작은 발걸음':tab==='guardian'?'너를 만나 달라진 나의 하루':'작은 발자국이 내 삶에 들어온 날';if(updateHistory)history.replaceState(null,'','#'+tab);}
function inputData(){const data={name:$('petName').value,date:$('petDate').value,mode:$('petMode').value};if(active==='saju')return E.pet(data);if(active==='guardian')return E.pair(E.pet(data),$('ownerDate').value);return E.friends(data,{name:$('friendName').value||'친구',date:$('friendDate').value,mode:$('friendMode').value});}
function showText(result){$('plainText').replaceChildren();const title=document.createElement('h2');title.className='reading-title';title.textContent=result.title;$('plainText').append(title);if(result.dateLine){const info=document.createElement('p');info.textContent=result.dateLine+' · '+result.tag;$('plainText').append(info);}result.paragraphs.forEach((text,index)=>{const p=document.createElement('p'),summary=index===result.paragraphs.length-1,parts=FortuneRenderer.emphasis(text,summary),strong=document.createElement('strong');strong.className=summary?'reading-summary':'reading-lead';strong.textContent=parts.lead;p.append(strong);if(parts.body)p.append(document.createTextNode(' '+parts.body));$('plainText').append(p);});$('basis').textContent=result.explanation;}
async function submit(){let g;try{const result=inputData();g=++generation;const tab=active;$('submit').disabled=true;$('form').setAttribute('aria-busy','true');$('error').textContent='';const item=await FortuneRenderer.card(result,modes[tab].kind);if(g!==generation){URL.revokeObjectURL(item.url);return;}if(current)URL.revokeObjectURL(current.url);current=item;$('resultImg').src=item.url;$('resultImg').alt=result.kind+' · '+result.title;$('resultTitle').textContent=result.kind;$('inputStage').hidden=true;$('resultStage').hidden=false;showText(result);$('resultTitle').focus();setupKakao();}catch(e){if(g===undefined||g===generation)$('error').textContent=e.message||'풀이를 만들지 못했어요. 다시 시도해주세요.';}finally{if(g===undefined||g===generation){$('submit').disabled=false;$('form').removeAttribute('aria-busy');}}}
$('form').addEventListener('submit',e=>{e.preventDefault();submit();});$('form').addEventListener('input',()=>{generation++;$('error').textContent='';$('submit').disabled=false;syncModeLabels();});
for(const id of ['petDate','friendDate','ownerDate'])$(id).max=E.today();
document.querySelectorAll('[data-tab]').forEach((b,index,buttons)=>{b.addEventListener('click',()=>choose(b.dataset.tab));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=e.key==='Home'?0:e.key==='End'?2:(index+(e.key==='ArrowRight'?1:2))%3;choose(buttons[i].dataset.tab);buttons[i].focus();});});
$('edit').addEventListener('click',()=>{clearResult();$('inputStage').hidden=false;$('petDate').focus();});window.addEventListener('hashchange',()=>{if(modes[location.hash.slice(1)])choose(location.hash.slice(1),false);});
function currentFile(){return new File([current.blob],`pet-fortune-${active}.png`,{type:'image/png'});}
function download(blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`pet-fortune-${active}.png`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('save').addEventListener('click',async()=>{if(!current)return;const file=currentFile();try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file]});$('status').textContent='공유 메뉴에서 이미지 저장을 선택해주세요.';}else{download(current.blob);$('status').textContent='이미지 다운로드를 요청했어요. 다운로드 폴더를 확인해주세요.';}}catch(e){if(e.name==='AbortError'){$('status').textContent='저장을 취소했어요.';return;}if(current)download(current.blob);$('status').textContent='이미지 파일 다운로드로 전환했어요.';}});
function shareUrl(){return location.origin+location.pathname+'#'+active;}
function shareText(){return `${current.result.kind}\n${current.result.title}\n\n${current.result.paragraphs.join('\n\n')}\n\n재미로 읽는 인연 이야기`;}
async function copyShare(){const text=shareText()+'\n'+shareUrl();try{await navigator.clipboard.writeText(text);$('status').textContent='풀이와 사이트 주소를 복사했어요. 카카오톡에 붙여넣어주세요.';}catch{$('manualCopy').hidden=false;$('copyText').value=text;$('copyText').focus();$('copyText').select();$('status').textContent='아래 내용을 복사해 카카오톡에 붙여넣어주세요.';}}
function setupKakao(){if(!/^[a-fA-F0-9]{32}$/.test(config.kakaoJavascriptKey||'')||shareReady)return;if(window.Kakao){if(!Kakao.isInitialized())Kakao.init(config.kakaoJavascriptKey);shareReady=true;$('share').textContent='카카오톡으로 공유';return;}if(document.getElementById('kakaoSdk'))return;const script=document.createElement('script');script.id='kakaoSdk';script.src='https://t1.kakaocdn.net/kakao_js_sdk/2.8.3/kakao.min.js';script.crossOrigin='anonymous';script.onload=()=>{try{setupKakao();}catch{script.remove();}};script.onerror=()=>script.remove();document.head.append(script);}
$('share').addEventListener('click',async()=>{if(!current)return;$('manualCopy').hidden=true;if(shareReady){try{Kakao.Share.sendDefault({objectType:'text',text:shareText().slice(0,1900),link:{mobileWebUrl:shareUrl(),webUrl:shareUrl()},buttonTitle:'나도 풀이 보기'});$('status').textContent='카카오톡에서 받을 사람을 직접 선택해주세요. 생년월일은 공유되지 않습니다.';return;}catch{}}
try{if(navigator.share){const file=currentFile();if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:current.result.title,text:current.result.kind});else await navigator.share({title:current.result.title,text:shareText(),url:shareUrl()});$('status').textContent='공유 메뉴에서 카카오톡을 선택할 수 있어요.';}else await copyShare();}catch(e){if(e.name==='AbortError'){$('status').textContent='공유를 취소했어요.';return;}if(current)await copyShare();}});
const initial=location.hash.slice(1);if(modes[initial])choose(initial,false);syncModeLabels();
